window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[204]={"id":"204","numero":204,"titre":"Toux chez l'enfant et chez l'adulte (avec et sans signes associés)","objectifs":[{"id":"204-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la toux aiguë et chronique chez l'enfant et l'adulte","contenu":"<p>La <span class=\"kw-def\">toux</span> est l'<strong>expulsion brusque et sonore de l'<span class=\"kw-def\">air</span> contenu dans <span class=\"kw-clinique\">les</span> poumons</strong>. C'est un phénomène <span class=\"kw-def\">réflexe physiologique</span>, indispensable à l'<strong>épuration et à la protection des voies aériennes</strong> :</p>\n      <ul>\n        <li>soit <strong>extériorisation</strong> des sécrétions bronchiques, trachéales et laryngées ;</li>\n        <li>soit <strong>réponse</strong> à toute irritation des voies aériennes.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\"><span class=\"kw-def\">Classification</span> selon la durée d'<span class=\"kw-clinique\">évolution</span></h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Durée</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Toux aiguë</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 3 semaines</span></td>\n            <td>Souvent secondaire aux <strong>infections respiratoires hautes d'origine <span class=\"kw-etio\">virale</span></strong> ; s'améliore spontanément.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Toux subaiguë</span></td>\n            <td><span class=\"kw-chiffre\">3 - 8 semaines</span></td>\n            <td>Zone transitionnelle.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Toux chronique</span></td>\n            <td><span class=\"kw-chiffre\">&gt; 8 semaines</span></td>\n            <td>Nécessite une PEC spécifique (même si isolée) ; <strong>ne s'améliore pas spontanément</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 La <strong>cassure à<span class=\"kw-chiffre\"> 8 semaines</span></strong> est l'horloge clé de l'item 204 : c'est elle qui bascule du registre <span class=\"kw-etio\">infectieux</span>/viral spontanément résolutif vers le bilan systématique <span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-bio\">spirométrie</span>.</div>","frequence":2},{"id":"204-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme du réflexe de toux","contenu":"<p>Le réflexe de <span class=\"kw-clinique\">toux</span> suit un <strong>arc à trois étages</strong> :</p>\n      <ol>\n        <li><strong>Afférent</strong> — <span class=\"kw-def\">neurorécepteurs sensoriels</span> (nocicepteurs + mécanorécepteurs) situés au niveau des <strong>VAS</strong> (<span class=\"kw-clinique\">larynx</span>, <span class=\"kw-clinique\">trachée</span>) et <strong>VAB</strong> (<span class=\"kw-clinique\">grosses bronches</span>) → relais par le <span class=\"kw-def\">nerf vague</span> → <span class=\"kw-def\">noyau du tractus solitaire (NTS)</span> au niveau du tronc cérébral.</li>\n        <li><strong>Central</strong> — intégration au NTS, connexion aux centres respiratoires ; <strong>contrôle cortical</strong> possible (commande volontaire pour <strong>inhiber</strong> OU <strong>activer</strong> la <span class=\"kw-clinique\">toux</span>).</li>\n        <li><strong>Efférent</strong> — réponse motrice → muscles respiratoires, larynx, bronches.</li>\n      </ol>\n\n      <div class=\"callout callout-warn\">⚠️ Il n'y a <span class=\"kw-alerte\">aucun récepteur au niveau alvéolaire</span> — la <span class=\"kw-clinique\">toux</span> ne se déclenche pas depuis l'alvéole. Point d'examen classique.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Sites de déclenchement extra-respiratoires</h4>\n      <ul>\n        <li><strong>Œsophage distal</strong> → explique pourquoi un <span class=\"kw-etio\">RGO</span> peut donner une <span class=\"kw-clinique\">toux</span> chronique.</li>\n        <li><strong>Conduit auditif externe</strong> (<span class=\"kw-def\">réflexe d'Arnold</span>) → un bouchon de cérumen peut déclencher une <span class=\"kw-clinique\">toux</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Récepteurs sensoriels — comparatif</h4>\n      <table >\n        <thead>\n          <tr><th></th><th>Nocicepteurs</th><th>Mécanorécepteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Stimulus</td>\n            <td>Irritants bronchiques</td>\n            <td>Stimuli mécaniques</td>\n          </tr>\n          <tr>\n            <td>Fibres / conduction</td>\n            <td>Fibres C, <strong>conduction lente</strong></td>\n            <td><span class=\"kw-def\">RARs</span> (récepteurs d'adaptation rapide), fibres Aδ myélinisées, <strong>conduction rapide</strong></td>\n          </tr>\n          <tr>\n            <td>Localisation</td>\n            <td>Larynx, trachée, bronches, parois alvéolaires</td>\n            <td>Larynx, trachée, bronches proximales</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":1},{"id":"204-3","rang":"A","rubrique":"Identifier une urgence","titre":"Rechercher les signes de gravité devant une toux aiguë ou chronique","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-alerte\">drapeaux rouges</span> 🚩</strong> sont à rechercher systématiquement devant toute <span class=\"kw-clinique\">toux</span>. Leur présence impose un <strong>bilan paraclinique sans délai</strong> (<span class=\"kw-imagerie\">RXT</span> ± <span class=\"kw-imagerie\">TDM thoracique</span>).</p>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Signes à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Signes généraux</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">AEG</span> :</strong> <span class=\"kw-clinique\">asthénie</span> ; anorexie ; <span class=\"kw-clinique\">amaigrissement</span><br>\n              <strong><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span> :</strong> <span class=\"kw-clinique\">fièvre</span> persistante ; sueurs\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <strong>Respiratoires :</strong> <span class=\"kw-alerte\">dyspnée d'effort</span> ; <span class=\"kw-alerte\">hémoptysie</span><br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> apparition ou modification de la <span class=\"kw-clinique\">toux</span> chez un fumeur<br>\n              <strong>ORL :</strong> <span class=\"kw-alerte\">dysphonie</span> ; <span class=\"kw-alerte\">dysphagie</span> ; <span class=\"kw-alerte\">fausses routes</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <strong>ADP :</strong> <span class=\"kw-alerte\">adénopathie(s) cervicale(s) suspecte(s)</span><br>\n              <strong>Cardiopulmonaire :</strong> anomalies de l'auscultation ou de l'inspection\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Spécificités pédiatriques — signes d'alerte 🚩 (<span class=\"kw-clinique\">toux</span> chronique de l'enfant)</h4>\n      <p>À rechercher à chaque évaluation devant une <span class=\"kw-clinique\">toux</span> chronique de l'enfant.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Signes à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Respiratoire</strong></td><td><span class=\"kw-alerte\">Encombrement bronchique permanent</span> ; <span class=\"kw-alerte\">wheezing ou stridor permanents</span> ; <span class=\"kw-alerte\">dyspnée aux 2 temps</span></td></tr>\n          <tr><td><strong>Digestif / nutritionnel</strong></td><td><span class=\"kw-alerte\">Fausses routes alimentaires</span> ; <span class=\"kw-alerte\">cassure de la croissance staturo-pondérale</span> ; <span class=\"kw-clinique\">diarrhée</span> chronique</td></tr>\n          <tr><td><strong>Cardiovasculaire</strong></td><td><span class=\"kw-alerte\">Malaise avec cyanose</span> ; souffle cardiaque</td></tr>\n          <tr><td><strong>État général</strong></td><td><span class=\"kw-clinique\">Altération de l'état général</span> ; limitation des activités ; retentissement sur le sommeil</td></tr>\n          <tr><td><strong>Autres</strong></td><td>Infections à répétition ou opportunistes ; déformation thoracique ; <span class=\"kw-alerte\">hippocratisme digital</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">🚨 Toute <span class=\"kw-clinique\">toux</span> qui <strong>s'installe ou change de caractère</strong> chez un fumeur de <span class=\"kw-chiffre\">&gt; 40 ans</span> = <span class=\"kw-alerte\">suspicion de cancer bronchique</span> jusqu'à preuve du contraire → <span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-imagerie\">TDM thoracique</span> sans délai.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span> · 205 — Hémoptysie · 309 — Tumeurs du poumon · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":1},{"id":"204-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la sémiologie d'une toux et les signes associés à la toux","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:var(--ink);\">Caractéristiques de la <span class=\"kw-clinique\">toux</span> à l'interrogatoire</h4>\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Détail</th><th>Orientation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Productive <span class=\"kw-bio\">vs</span> sèche</strong></td>\n            <td><span class=\"kw-clinique\">Toux</span> sèche / toux grasse</td>\n            <td>\n              <strong>Sèche :</strong> <span class=\"kw-etio\">asthme</span> ; <span class=\"kw-etio\">fibrose pulmonaire</span><br>\n              <strong>Productive :</strong> <span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">dilatation des bronches</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaire</strong></td>\n            <td>Diurne / nocturne / matinale</td>\n            <td>\n              <strong>Nocturne :</strong> <span class=\"kw-etio\">asthme</span> ; <span class=\"kw-etio\">RGO</span><br>\n              <strong>Diurne pure :</strong> <span class=\"kw-clinique\">toux</span> par excès de sensibilité ; toux psychogène\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ancienneté</strong></td>\n            <td>Aigu, subaigu, chronique</td>\n            <td>Cf. obj-0 (cassure à <span class=\"kw-chiffre\">8 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Circonstances déclenchantes</strong></td>\n            <td>Effort ; décubitus ; repas ; <span class=\"kw-def\">air</span> froid ; parfums</td>\n            <td>\n              <strong>Effort/froid :</strong> <span class=\"kw-etio\">asthme</span><br>\n              <strong>Décubitus/repas :</strong> <span class=\"kw-etio\">RGO</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Signes associés à rechercher</h4>\n      <table >\n        <thead>\n          <tr><th>Signe associé</th><th>Étiologie évoquée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Pyrosis</span></strong> ; <span class=\"kw-clinique\">régurgitations</span> acides</td>\n            <td><span class=\"kw-etio\">RGO</span></td>\n          </tr>\n          <tr>\n            <td><strong>Jetage postérieur</strong> ; rhinorrhée ; obstruction nasale</td>\n            <td><span class=\"kw-etio\">rhinosinusite chronique (STOVAS)</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Sibilants</span></strong> ; <span class=\"kw-clinique\">dyspnée d'effort</span></td>\n            <td><span class=\"kw-etio\">asthme</span></td>\n          </tr>\n          <tr>\n            <td><strong>Pyrexie</strong> ; <span class=\"kw-clinique\">expectoration</span> purulente</td>\n            <td><span class=\"kw-etio\">infection respiratoire</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Complications de la <span class=\"kw-clinique\">toux</span></h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sociales</strong></td>\n            <td>Gêne professionnelle ; <span class=\"kw-def\">isolement</span> ; arrêt de travail</td>\n          </tr>\n          <tr>\n            <td><strong>Psychologiques</strong></td>\n            <td><span class=\"kw-clinique\">Dépression</span> ; <span class=\"kw-clinique\">anxiété</span></td>\n          </tr>\n          <tr>\n            <td><strong>Physiques</strong></td>\n            <td>\n              <strong>Sommeil :</strong> troubles du sommeil (<span class=\"kw-clinique\">toux</span> nocturne)<br>\n              <strong>Mécaniques :</strong> <span class=\"kw-clinique\">céphalées</span> ; vomissements ; <span class=\"kw-alerte\">fractures de côtes</span> ; <span class=\"kw-alerte\">hernie inguinale</span><br>\n              <strong>Urinaires :</strong> <span class=\"kw-alerte\">incontinence urinaire</span> (<span class=\"kw-chiffre\">2/3 des femmes</span> +++)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Digestives</strong></td>\n            <td>Aggravation d'un <span class=\"kw-clinique\">RGO</span> préexistant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span> · 205 — Hémoptysie · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":1},{"id":"204-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","contenu":"<p><strong>Définition rappel :</strong> <span class=\"kw-clinique\">toux</span> aiguë = <span class=\"kw-chiffre\">&lt; 3 semaines</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies — hiérarchisées par fréquence</h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Infections respiratoires hautes</strong> (<span class=\"kw-clinique\">les</span> plus fréquentes +++)</td>\n            <td>\n              <strong>Virales :</strong> <span class=\"kw-etio\">rhinopharyngite aiguë</span> ; <span class=\"kw-etio\">rhino-sinusite aiguë</span><br>\n              <strong>Démarche :</strong> souvent <span class=\"kw-etio\">virale</span>, spontanément résolutive ; pas d'examen complémentaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infections respiratoires basses</strong></td>\n            <td>\n              <strong>Bactériennes/virales :</strong> <span class=\"kw-etio\">bronchite aiguë</span> ; plus rarement <span class=\"kw-etio\">pneumonie</span><br>\n              <strong>Renvoi :</strong> cf. item 154\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Affections chroniques en <span class=\"kw-clinique\">poussée</span></strong></td>\n            <td>\n              <strong>Respiratoires :</strong> <span class=\"kw-etio\">asthme</span> ; <span class=\"kw-etio\">BPCO</span><br>\n              <strong>Digestives :</strong> <span class=\"kw-etio\">RGO</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes rares à ne pas manquer</strong></td>\n            <td>\n              <strong>Cardiaques :</strong> <span class=\"kw-alerte\">insuffisance cardiaque gauche</span><br>\n              <strong>Vasculaires :</strong> <span class=\"kw-alerte\">embolie pulmonaire</span><br>\n              <strong>Pleuro-pulmonaires :</strong> <span class=\"kw-alerte\">pneumothorax</span> ; <span class=\"kw-alerte\">pleurésies</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Spécificités pédiatriques — <span class=\"kw-clinique\">toux</span> aiguë de l'enfant (selon le caractère)</h4>\n      <table >\n        <thead><tr><th>Type de toux</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Grasse</strong></td><td><span class=\"kw-etio\">Rhinopharyngite</span>, <span class=\"kw-etio\">infection ORL</span> : <span class=\"kw-clinique\">toux</span> majorée au décubitus, rhinite, ± fébricule</td></tr>\n          <tr><td><strong>Sèche</strong></td><td><span class=\"kw-etio\">Asthme</span>, <span class=\"kw-etio\">bronchiolite</span> (± <span class=\"kw-clinique\">wheezing</span>, dyspnée, sibilants) ; <span class=\"kw-etio\">pneumonie</span> (<span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">polypnée</span>, crépitants en foyer) ; <span class=\"kw-etio\">coqueluche</span> (<span class=\"kw-clinique\">toux</span> quinteuse, ± <span class=\"kw-ttt\">vaccination</span> incomplète) ; <span class=\"kw-alerte\">corps étranger inhalé</span> (toux brutale, syndrome d'inhalation, ± dyspnée)</td></tr>\n          <tr><td><strong>Rauque</strong></td><td><span class=\"kw-etio\">Laryngite</span> : rhinite, ± <span class=\"kw-clinique\">dyspnée</span> inspiratoire, ± fébricule</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan clinique (ECOS)</h4>\n      <ul>\n        <li><strong>Interrogatoire :</strong> caractéristiques de la <span class=\"kw-clinique\">toux</span> + profil patient (ATCD, traitements, <span class=\"kw-def\">comorbidités</span>, tabac, profession).</li>\n        <li><strong>Inspection :</strong> <span class=\"kw-clinique\">fosses nasales</span> ; <span class=\"kw-clinique\">conduits auditifs</span> ; <span class=\"kw-clinique\">cavité buccale</span>.</li>\n        <li><strong><span class=\"kw-alerte\">Auscultation cardio-pulmonaire</span> :</strong> <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan paraclinique</h4>\n      <p>Pas d'examen complémentaire dans la majorité des cas ❌ — <span class=\"kw-imagerie\">RXT</span> possible <strong>uniquement</strong> si examen clinique anormal.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\"><span class=\"kw-def\">Suivi</span> et prise en charge initiale</h4>\n      <ul>\n        <li>Organiser un <strong><span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">4 - 6 semaines</span></strong> pour s'assurer de la <strong>résolution spontanée</strong> de la <span class=\"kw-clinique\">toux</span> aiguë.</li>\n        <li><strong>Pas d'<span class=\"kw-ttt\">antibiothérapie</span></strong> sauf <span class=\"kw-etio\">infection bactérienne avérée</span> (rare en ambulatoire).</li>\n        <li><strong>Pas d'antitussifs</strong> en routine — rapport bénéfice/risque défavorable (cf. obj-8).</li>\n        <li><strong>Conseil systématique :</strong> <span class=\"kw-clinique\">arrêt définitif du tabac</span> avec aide au <span class=\"kw-ttt\">sevrage</span> si fumeur actif.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ Le réflexe à <strong>ne pas</strong> avoir = prescrire d'emblée une <span class=\"kw-imagerie\">RXT</span> ou des antibiotiques sur une <span class=\"kw-clinique\">toux</span> aiguë sans signe d'alerte. La majorité des toux aiguës sont virales et s'amendent en <span class=\"kw-chiffre\">7 - 10 jours</span> sans rien.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire · 188 — Asthme - Rhinite · 209 — BPCO · 226 — Thrombose veineuse profonde - EP · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 360 — Pneumothorax · 206 — Epanchement pleural · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":2},{"id":"204-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","contenu":"<p><strong>Définition rappel :</strong> <span class=\"kw-clinique\">toux</span> chronique = <span class=\"kw-chiffre\">&gt; 8 semaines</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies — hiérarchisées de la plus fréquente à la plus rare</h4>\n      <table >\n        <thead>\n          <tr><th>Fréquence</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Triade fréquente</strong> (à évoquer en 1<sup>er</sup>)</td>\n            <td>\n              <strong>Voies aériennes hautes :</strong> <span class=\"kw-etio\">rhinosinusite chronique (STOVAS)</span> = syndrome de <span class=\"kw-clinique\">toux</span> d'origine des voies aériennes supérieures<br>\n              <strong>Voies aériennes basses :</strong> <span class=\"kw-etio\">asthme</span><br>\n              <strong>Digestive :</strong> <span class=\"kw-etio\">RGO</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes</strong></td>\n            <td>\n              <strong>Médicamenteuses :</strong> <span class=\"kw-ttt\">IEC</span> (<span class=\"kw-clinique\">toux</span> sèche, délai d'apparition jusqu'à <span class=\"kw-chiffre\">6 mois</span> après instauration, à rechercher systématiquement avant tout bilan poussé)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladies bronchiques chroniques</strong></td>\n            <td><span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">dilatation des bronches</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cancers</strong></td>\n            <td><span class=\"kw-alerte\">Cancer bronchique</span> (à évoquer chez tout fumeur <span class=\"kw-chiffre\">&gt; 40 ans</span> avec <span class=\"kw-clinique\">toux</span> récente ou modifiée)</td>\n          </tr>\n          <tr>\n            <td><strong>Pneumopathies infiltratives</strong></td>\n            <td><span class=\"kw-etio\">Pneumopathies interstitielles diffuses (PID)</span> ; <span class=\"kw-etio\">sarcoïdose</span> (étiologie moins fréquente mais classique)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Toux</span> réfractaires/inexpliquées</strong></td>\n            <td><span class=\"kw-def\">TOCRI / Syndrome de toux par excès de sensibilité</span> — voir focus ci-dessous</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:var(--ink);\">Focus — TOCRI (Syndrome de <span class=\"kw-clinique\">toux</span> par excès de sensibilité)</h4>\n      <table >\n        <thead>\n          <tr><th>Aspect</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Physiopath</strong></td>\n            <td>Sensibilisation des voies neurologiques de la <span class=\"kw-clinique\">toux</span> → <strong>hyperréactivité</strong> (≈ <span class=\"kw-def\">douleur neuropathique</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Irritation / paresthésies des VAS</span> (larynx, pharynx) ;<br>\n              <span class=\"kw-clinique\">Hypertussie</span> (déclenchement par stimuli peu tussigènes) ;<br>\n              <span class=\"kw-clinique\">Allotussie</span> (déclenchement par stimuli non tussigènes : parole, rire) ;<br>\n              <span class=\"kw-clinique\">Toux</span> paroxystique difficile à contrôler.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Déclencheurs</strong></td>\n            <td>\n              <strong>Mécaniques :</strong> parole ; rire ; respiration profonde<br>\n              <strong>Thermo :</strong> <span class=\"kw-def\">air</span> froid<br>\n              <strong>Chimio :</strong> parfums ; aérosols<br>\n              <strong>Autres :</strong> décubitus ; repas ; exercice\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td><span class=\"kw-ttt\">Prégabaline</span> ou <span class=\"kw-ttt\">gabapentine</span> (anti-épileptiques) + <span class=\"kw-ttt\">morphine à faible dose</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ Toujours rechercher un <span class=\"kw-ttt\">IEC</span> à l'interrogatoire <strong>AVANT</strong> toute exploration — c'est le piège classique de la <span class=\"kw-clinique\">toux</span> chronique <span class=\"kw-etio\">iatrogène</span>. L'arrêt de l'<span class=\"kw-ttt\">IEC</span> précède le bilan.</div>\n\n      <h4 style=\"margin:18px 0 6px;font-size:14px;color:var(--ink);\">Spécificités pédiatriques — orientation devant une <span class=\"kw-clinique\">toux</span> chronique de l'enfant</h4>\n      <p>L'analyse du <strong>caractère de la <span class=\"kw-clinique\">toux</span></strong> (sèche ou grasse) est fondamentale chez l'enfant.</p>\n      <table >\n        <thead><tr><th>Caractère de la toux</th><th>Contexte / signes</th><th>Diagnostic probable</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sèche, récurrente</strong></td><td>Virose hivernale</td><td><span class=\"kw-etio\">Hyperréactivité bronchique post-virale</span></td></tr>\n          <tr><td><strong>Sèche, prédominance 2<sup>e</sup> partie de nuit</strong></td><td>Atopie, <span class=\"kw-clinique\">wheezing</span>, saisonnalité, réponse aux β₂</td><td><span class=\"kw-etio\">Asthme</span></td></tr>\n          <tr><td><strong>Sèche, quinteuse</strong></td><td>Contage, <span class=\"kw-ttt\">vaccination</span> incomplète, auscultation normale</td><td><span class=\"kw-etio\">Coqueluche</span></td></tr>\n          <tr><td><strong>Grasse</strong></td><td>Jetage postérieur, obstruction nasale</td><td><span class=\"kw-etio\">Infection ORL chronique</span></td></tr>\n          <tr><td><strong>Grasse, isolée et continue <span class=\"kw-chiffre\">≥ 4 semaines</span></strong></td><td>Âge préscolaire, état général conservé, <span class=\"kw-clinique\">râles</span> bronchiques</td><td><span class=\"kw-etio\">Bronchite bactérienne persistante (BBP)</span></td></tr>\n          <tr><td><strong>Grasse, <span class=\"kw-clinique\">expectoration</span></strong></td><td>Début précoce, <span class=\"kw-alerte\">cassure pondérale</span>, <span class=\"kw-alerte\">hippocratisme digital</span>, <span class=\"kw-clinique\">crépitants</span></td><td><span class=\"kw-etio\">Mucoviscidose</span> ; autres dilatations des bronches (DDB)</td></tr>\n          <tr><td><strong>Variable, rythmée par l'alimentation</strong></td><td>Début précoce, <span class=\"kw-alerte\">fausses routes</span> ± <span class=\"kw-clinique\">cyanose</span> ± <span class=\"kw-clinique\">malaise</span></td><td><span class=\"kw-etio\">Pathologie laryngée</span> ; <span class=\"kw-etio\">fistule œsotrachéale</span></td></tr>\n          <tr><td><strong>Aboyante, diurne, s'arrêtant sur commande</strong></td><td><span class=\"kw-def\">Terrain</span> anxieux, tics, pas de déclencheur</td><td><span class=\"kw-def\">Toux psychogène</span> possible</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — Asthme - Rhinite · 209 — BPCO · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale · 309 — Tumeurs du poumon · 210 — Pneumopathie interstitielle diffuse · 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique · 154 — Infection bronchopulmonaire communautaire</em></p>","frequence":4},{"id":"204-7","rang":"A","rubrique":"Contenu multimédia","titre":"Exemples caractéristiques de radiographie thoracique","contenu":"<p>La planche officielle illustre le <span class=\"kw-def\">syndrome bronchique</span> (dilatation des bronches), exemple caractéristique de <span class=\"kw-imagerie\">radiographie thoracique</span> à reconnaître. <span class=\"kw-clinique\">Les</span> autres étiologies relèvent d'items dédiés : pneumopathie interstitielle → <strong>item 210</strong> ; opacités et masses intra-thoraciques → <strong>item 207</strong>. Le <span class=\"kw-etio\">corps étranger inhalé</span> (clichés en <span class=\"kw-imagerie\">inspiration / expiration</span>) est abordé dans le volet pédiatrique de cet item.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/204/rp-syndrome-bronchique-ddb.png\" alt=\"Radiographie de thorax de face montrant un syndrome bronchique de dilatation des bronches : images en cibles correspondant à des bronches dilatées à parois épaisses, images en rail, et nodule bien limité correspondant à une impaction mucoïde ; schéma comparatif de bronches normales\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie de thorax de face</span> — <span class=\"kw-def\">syndrome bronchique</span> (dilatation des bronches). <span class=\"kw-radio\">Images en cibles</span> correspondant à des bronches dilatées à parois épaisses ; <span class=\"kw-radio\">images en rail</span> ; <span class=\"kw-radio\">nodule bien limité</span> correspondant à une <span class=\"kw-radio\">impaction mucoïde</span>. Le schéma de gauche oppose le réseau de bronches normales aux bronches dilatées. Source : banque imagerie « Imagerie à connaître » (item 204).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 210 — Pneumopathie interstitielle diffuse</em></p>","frequence":0},{"id":"204-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication des examens d'imagerie devant une toux de l'enfant et de l'adulte","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:var(--ink);\"><span class=\"kw-clinique\">Toux</span> aiguë</h4>\n      <ul>\n        <li>Pas d'examen complémentaire dans la majorité des cas ❌.</li>\n        <li><span class=\"kw-imagerie\">RXT</span> possible si examen clinique anormal.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\"><span class=\"kw-clinique\">Toux</span> chronique — bilan paraclinique initial systématique</h4>\n      <ul>\n        <li><strong>Bilan systématique :</strong> <span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-bio\">spirométrie</span>.</li>\n        <li><span class=\"kw-imagerie\">TDM thoracique</span> : <strong>PAS d'indication systématique</strong> si <span class=\"kw-clinique\">les</span> <strong>3 critères</strong> suivants sont remplis :\n          <ul>\n            <li>Examen clinique normal,</li>\n            <li><span class=\"kw-imagerie\">RXT</span> normale,</li>\n            <li>Pas de FR de cancer bronchique (<span class=\"kw-etio\">tabagisme</span> important, exposition amiante, ATCD familiaux…).</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Récapitulatif des indications d'imagerie</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications</th><th>Quand y penser</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">RXT</span></td>\n            <td><span class=\"kw-clinique\">Toux</span> aiguë avec examen anormal ; toux chronique systématique</td>\n            <td>1<sup>re</sup> ligne</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM thoracique</span></td>\n            <td><span class=\"kw-imagerie\">RXT</span> anormale ; <span class=\"kw-alerte\">FR cancer bronchique</span> ; examen clinique anormal ; <span class=\"kw-clinique\">toux</span> résistante au traitement d'épreuve</td>\n            <td>Après échec de la 1<sup>re</sup> ligne</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Spirométrie</span></td>\n            <td><span class=\"kw-clinique\">Toux</span> chronique systématique — recherche d'un <span class=\"kw-def\">trouble ventilatoire obstructif</span> ou <span class=\"kw-def\">restrictif</span></td>\n            <td>Couplée à la <span class=\"kw-imagerie\">RXT</span> au bilan initial</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong> (<span class=\"kw-imagerie\">fibroscopie bronchique</span>, <span class=\"kw-imagerie\">TDM sinus</span>, <span class=\"kw-bio\">pH-métrie œsophagienne</span>…)</td>\n            <td>Selon orientation étiologique</td>\n            <td>Adaptés au contexte</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Spécificités pédiatriques — imagerie de la <span class=\"kw-clinique\">toux</span> chronique de l'enfant</h4>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">RXT de face</span> systématique</strong> devant toute <span class=\"kw-clinique\">toux</span> chronique de l'enfant, pour orienter le diagnostic.</li>\n        <li><span class=\"kw-clinique\">Toux</span> &gt;<span class=\"kw-chiffre\"> 8 semaines</span> : <strong><span class=\"kw-imagerie\">cliché thoracique</span> de face en <span class=\"kw-imagerie\">inspiration ET expiration</span></strong> (recherche d'un <span class=\"kw-alerte\">corps étranger inhalé</span> par trappage expiratoire).</li>\n        <li>Absence d'orientation et pas de signe d'alerte : <span class=\"kw-bio\">EFR</span> + bilan allergologique + avis ORL.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ Pas de <span class=\"kw-imagerie\">TDM</span> en <span class=\"kw-chiffre\">première intention</span> sur une <span class=\"kw-clinique\">toux</span> chronique sans <span class=\"kw-def\">facteur de risque</span> ni anomalie clinique/radio — c'est un piège QCM classique sur l'item 204.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 309 — Tumeurs du poumon · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":2},{"id":"204-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement symptomatique de la toux","contenu":"<p><strong>Principe :</strong> <span class=\"kw-clinique\">les</span> antitussifs n'ont <strong>pas lieu d'être prescrits</strong> en routine — rapport bénéfice/risque faible : efficacité non démontrée, effets secondaires parfois importants. Le traitement repose sur la <strong>PEC étiologique</strong> (cf. obj-9).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\"><span class=\"kw-def\">Classification</span> des antitussifs</h4>\n      <table >\n        <thead>\n          <tr><th>Site d'action</th><th>Classe</th><th>Exemples (DCI)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"4\"><strong>Action centrale</strong></td>\n            <td><span class=\"kw-ttt\">Opiacés narcotiques</span></td>\n            <td><span class=\"kw-ttt\">codéine</span> ; <span class=\"kw-ttt\">pholcodine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Opiacés non narcotiques</span></td>\n            <td><span class=\"kw-ttt\">dextrométhorphane</span> ; <span class=\"kw-ttt\">noscapine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Anti-histaminiques H1 sédatifs</span></td>\n            <td><span class=\"kw-ttt\">alimémazine</span> ; <span class=\"kw-ttt\">prométhazine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Non opiacé, non anti-histaminique</span></td>\n            <td><span class=\"kw-ttt\">oxéladine</span> ; <span class=\"kw-ttt\">pentoxyvérine</span> ; <span class=\"kw-ttt\">clobutinol</span></td>\n          </tr>\n          <tr>\n            <td><strong>Action périphérique</strong></td>\n            <td>Anesthésiques / chimiques</td>\n            <td>Chlorhydrate d'amyléine ; aconitine ; benzoate de sodium</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\"><span class=\"kw-ci\">Contre-indications</span> majeures à connaître</h4>\n      <ul>\n        <li><span class=\"kw-ci\">Codéine</span> : <span class=\"kw-alerte\">contre-indiquée chez l'enfant &lt; 12 ans</span> (rappel ANSM — risque dépression respiratoire) ; <span class=\"kw-ci\">à éviter</span> chez l'allaitante (passage lacté variable selon le métabolisme CYP2D6 maternel).</li>\n        <li><span class=\"kw-ci\">Opiacés en général</span> : prudence chez l'insuffisant respiratoire chronique, le sujet âgé, l'insuffisant hépatique.</li>\n        <li><span class=\"kw-ci\">Antitussifs sur toux productive</span> : déconseillés (ils bloquent le réflexe d'épuration bronchique).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Mesures non médicamenteuses systématiques</h4>\n      <ul>\n        <li><strong>Arrêt du tabac</strong> : conseil systématique, avec aide au <span class=\"kw-ttt\">sevrage</span> si fumeur actif.</li>\n        <li>Hydratation.</li>\n        <li>Évitement des facteurs déclenchants identifiés.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">🚨 La <span class=\"kw-alerte\">codéine est contre-indiquée chez l'enfant de moins de 12 ans</span> depuis 2013 (ANSM, EMA) — c'est un piège QCM récurrent.</div>","frequence":1},{"id":"204-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les éléments de prise en charge étiologique","contenu":"<p><strong>Principe général :</strong> le traitement est avant tout <strong>étiologique +++</strong>. Le traitement symptomatique a peu de place. L'<strong>arrêt du tabac</strong> est conseillé dans tous <span class=\"kw-clinique\">les</span> cas (aide au <span class=\"kw-ttt\">sevrage</span> définitif si nécessaire).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Traitement d'épreuve — triade des étiologies <span class=\"kw-clinique\">les</span> plus fréquentes</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Traitement d'épreuve</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Rhinosinusite chronique (STOVAS)</span></td>\n            <td><strong><span class=\"kw-ttt\">Corticothérapie</span> nasale</strong> + lavage des fosses nasales + éviction des facteurs favorisants</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Asthme</span></td>\n            <td><span class=\"kw-ttt\">CSI</span> (<span class=\"kw-ttt\">corticoïdes</span> inhalés) ± <span class=\"kw-ttt\">BDLA</span> (bêta-2-mimétique de longue durée d'action)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">RGO</span></td>\n            <td><span class=\"kw-ttt\">IPP</span> pendant <span class=\"kw-chiffre\">≥ 8 semaines</span> + <span class=\"kw-ttt\">règles hygiéno-diététiques</span> (++) — <span class=\"kw-ttt\">IPP</span> justifiés <strong>uniquement</strong> s'il existe des signes de <span class=\"kw-clinique\">RGO</span> (pyrosis, régurgitations acides)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Arbre décisionnel — démarche devant une <span class=\"kw-clinique\">toux</span> chronique</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Action</th><th>Suite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>0</strong></td>\n            <td><span class=\"kw-clinique\">Toux</span> chronique <span class=\"kw-chiffre\">&gt; 8 semaines</span> confirmée</td>\n            <td>→ Étape 1</td>\n          </tr>\n          <tr>\n            <td><strong>1</strong></td>\n            <td>Interrogatoire (médicaments, tabac) + examen clinique + <span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-bio\">spirométrie</span></td>\n            <td>→ Étape 2 ou 3 selon résultat</td>\n          </tr>\n          <tr>\n            <td><strong>2a</strong></td>\n            <td>Si <span class=\"kw-ttt\">IEC</span> identifié</td>\n            <td><strong>Arrêt de l'<span class=\"kw-ttt\">IEC</span></strong> → <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">1 - 3 mois</span></td>\n          </tr>\n          <tr>\n            <td><strong>2b</strong></td>\n            <td>Si <span class=\"kw-imagerie\">RXT</span> / <span class=\"kw-bio\">spirométrie</span> anormale</td>\n            <td>Bilan ciblé selon anomalie (<span class=\"kw-imagerie\">TDM</span>, fibro bronchique, etc.)</td>\n          </tr>\n          <tr>\n            <td><strong>3</strong></td>\n            <td>Si bilan initial normal</td>\n            <td><strong>Traitement d'épreuve séquentiel</strong> sur la triade : STOVAS (<span class=\"kw-ttt\">corticoïdes</span> nasaux) → asthme (<span class=\"kw-ttt\">CSI</span> ± <span class=\"kw-ttt\">BDLA</span>) → <span class=\"kw-clinique\">RGO</span> (<span class=\"kw-ttt\">IPP</span> <span class=\"kw-chiffre\">8 semaines</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>4</strong></td>\n            <td>Si échec des 3 traitements d'épreuve</td>\n            <td>Bilan de 2<sup>e</sup> ligne (<span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-bio\">pH-métrie</span>, fibro, ORL) + évoquer <span class=\"kw-def\">TOCRI</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ Le <strong>traitement d'épreuve séquentiel</strong> sur la triade <span class=\"kw-etio\">STOVAS</span> / <span class=\"kw-etio\">asthme</span> / <span class=\"kw-etio\">RGO</span> est la démarche EDN canonique — il faut le savoir par cœur et savoir l'expliquer en 30 secondes.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Spécificités pédiatriques — prise en charge de la <span class=\"kw-clinique\">toux</span> de l'enfant</h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mesures générales</strong></td><td>Respecter une <span class=\"kw-clinique\">toux</span> productive (évacuation des sécrétions) ; hydratation régulière (fluidifie <span class=\"kw-clinique\">les</span> sécrétions)</td></tr>\n          <tr><td><strong>Traitement étiologique</strong> (essentiel)</td><td>Spécifique après confirmation diagnostique ; traitement d'épreuve probabiliste si <span class=\"kw-clinique\">toux</span> chronique non spécifique isolée : toux sèche → <span class=\"kw-ttt\">corticoïde inhalé</span> (éventualité d'asthme), toux grasse → <span class=\"kw-ttt\">antibiothérapie probabiliste</span> (éventualité d'une BBP)</td></tr>\n          <tr><td><strong>Symptomatique</strong></td><td>Encombrement nasal → <span class=\"kw-ttt\">désobstruction rhinopharyngée</span> au sérum physiologique ; encombrement bronchique → <span class=\"kw-ttt\">kinésithérapie respiratoire</span> ; contrôle des facteurs environnementaux (allergènes, tabac, pollution, humidité)</td></tr>\n          <tr><td><strong>À éviter</strong></td><td><span class=\"kw-ci\">Antitussifs</span> : place très limitée, efficacité non démontrée, <span class=\"kw-alerte\">contre-indiqués chez le nourrisson</span></td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — Asthme - Rhinite · 209 — BPCO · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":4}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-clinique\">toux</span> <span class=\"kw-clinique\">rarement une urgence vitale</span> en soi, mais <span class=\"kw-alerte\">signes de gravité</span> à rechercher à chaque évaluation<br><strong>Fenêtre :</strong> aiguë <span class=\"kw-chiffre\">&lt; 3 semaines</span> ; subaiguë <span class=\"kw-chiffre\">3-8 semaines</span> ; chronique <span class=\"kw-chiffre\">&gt; 8 semaines</span><br><strong>1er geste :</strong> <span class=\"kw-clinique\">auscultation cardio-pulmonaire</span> obl<span class=\"kw-chiffre\">iga</span>toire ; <span class=\"kw-imagerie\">RXT</span> si examen clinique anormal</p>","hospit":"<p><strong><span class=\"kw-clinique\">Toux</span> aiguë :</strong> prise en charge <span class=\"kw-ttt\">ambulatoire</span> ; pas d'examen complémentaire en routine ; <span class=\"kw-imagerie\">RXT</span> seulement si clinique anormale<br><strong>Toux chronique :</strong> bilan <span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-imagerie\">spirométrie</span> systématique (chez l'enfant <span class=\"kw-imagerie\">RXT de face</span> systématique)<br><strong>Avis spécialisé :</strong> si <span class=\"kw-alerte\">signes d'alerte</span> ou anomalie radiographique → bilan exhaustif (ORL, <span class=\"kw-imagerie\">EFR</span>, <span class=\"kw-imagerie\">TDM</span>...)</p>","redflags":"<p><strong>Adulte</strong></p><ul><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span></li><li><span class=\"kw-clinique\">Dyspnée d'effort</span>, <span class=\"kw-alerte\">hémoptysie</span></li><li>Apparition ou modification de la <span class=\"kw-clinique\">toux</span> chez un <span class=\"kw-alerte\">fumeur</span></li><li><span class=\"kw-clinique\">Dysphonie</span>, <span class=\"kw-clinique\">dysphagie</span>, fausses routes</li><li><span class=\"kw-clinique\">Adénopathie cervicale suspecte</span> ; anomalie de l'examen cardio-pulmonaire</li></ul><p><strong>Enfant (signes d'alerte, à chaque évaluation)</strong></p><ul><li>Respiratoire : encombrement bronchique permanent, <span class=\"kw-clinique\">wheezing ou stridor permanents</span>, <span class=\"kw-clinique\">dyspnée</span> aux 2 temps</li><li>Digestif/nutritionnel : <span class=\"kw-alerte\">fausses routes alimentaires</span>, cassure staturo-pondérale, <span class=\"kw-clinique\">diarrhée</span> chronique</li><li>Cardiovasculaire : <span class=\"kw-alerte\">malaise avec cyanose</span>, souffle cardiaque</li><li>État général : <span class=\"kw-alerte\">AEG</span>, limitation des activités, retentissement sur le sommeil</li><li>Autres : infections à répétition ou opportunistes, déformation thoracique, <span class=\"kw-clinique\">hippocratisme digital</span></li></ul>","principes":"<p>Traiter la cause avant tout ; le traitement symptomatique a peu de place et <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antitussifs</span> sont rarement utiles.</p><p><strong>Règles communes</strong></p><ul><li>Priorité au <span class=\"kw-ttt\">traitement étiologique</span> ++</li><li><span class=\"kw-ttt\">Sevrage tabagique</span> conseillé dans tous <span class=\"kw-clinique\">les</span> cas (aide au <span class=\"kw-ttt\">sevrage</span>)</li><li><span class=\"kw-ttt\">Antitussifs</span> : place très limitée, rapport bénéfice/risque faible</li></ul><p><strong><span class=\"kw-clinique\">Toux</span> aiguë</strong></p><ul><li>Le plus souvent <span class=\"kw-etio\">virale</span> (infection respiratoire haute), résolutive spontanément</li><li>Pas d'<span class=\"kw-ttt\">antibiotique</span> sauf infection <span class=\"kw-etio\">bactérienne</span> avérée ; pas d'<span class=\"kw-ttt\">antitussif</span></li><li>Aucune PEC spécifique hormis un <span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">4-6 semaines</span></li></ul><p><strong>Traitement d'épreuve (<span class=\"kw-clinique\">toux</span> chronique, adulte)</strong></p><p>Traitement d'épreuve ciblé sur le diagnostic le plus probable parmi <span class=\"kw-clinique\">les</span> 3 causes fréquentes.</p><ul><li>STOVAS / rhinosinusite : <span class=\"kw-ttt\">corticothérapie nasale</span> + lavage du nez</li><li>Asthme : <span class=\"kw-ttt\">CSI</span> ± <span class=\"kw-ttt\">BDLA</span></li><li><span class=\"kw-clinique\">RGO</span> : <span class=\"kw-ttt\">IPP</span> pendant <span class=\"kw-chiffre\">≥ 8 semaines</span> + <span class=\"kw-ttt\">règles hygiéno-diététiques</span> (si signes de RGO)</li></ul><p><strong><span class=\"kw-clinique\">Toux</span> réfractaire / TOCRI</strong></p><ul><li>Syndrome de <span class=\"kw-clinique\">toux</span> par <span class=\"kw-etio\">excès de sensibilité</span></li><li><span class=\"kw-ttt\">Anti-épileptiques</span> (<span class=\"kw-ttt\">prégabaline</span> ou <span class=\"kw-ttt\">gabapentine</span>) + <span class=\"kw-ttt\">morphine</span> à faible dose</li></ul><p><strong>Spécificités enfant</strong></p><ul><li>Symptomatique : <span class=\"kw-ttt\">désobstruction rhinopharyngée</span> (sérum physiologique), <span class=\"kw-ttt\">kinésithérapie respiratoire</span> si encombrement</li><li>Traitement d'épreuve : <span class=\"kw-clinique\">toux</span> sèche → <span class=\"kw-ttt\">corticoïde inhalé</span> (asthme) ; toux grasse → <span class=\"kw-ttt\">ATB probabiliste</span> (bronchite <span class=\"kw-etio\">bactérienne</span> persistante)</li><li><span class=\"kw-ttt\">Antitussifs</span> <span class=\"kw-ci\">contre-indiqués chez le nourrisson</span></li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Toux</span> aiguë :</strong> <span class=\"kw-def\">suivi</span> à <span class=\"kw-chiffre\">4-6 semaines</span> pour vérifier la disparition de la toux<br><strong>Toux chronique :</strong> réévaluer la réponse au <span class=\"kw-ttt\">traitement d'épreuve</span> ; relais vers un bilan approfondi si persistance<br><strong>Après <span class=\"kw-ttt\">sevrage</span> :</strong> à l'arrêt du tabac ou des tussigènes (<span class=\"kw-ttt\">IEC</span>), la toux peut transitoirement s'aggraver avant amélioration (délai variable)</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/toux","label":"Pedia-univ — Toux"},{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_204_TOUX_2023.pdf","label":"Collège (CEP) — Item 204 toux 2023"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Toux chronique de l'adulte (> 8 semaines) — Bilan initial : examen clinique + RXT + spirométrie","detail":"<h4>CAT — <span class=\"kw-clinique\">Toux</span> chronique de l'adulte (<span class=\"kw-chiffre\">> 8 semaines</span>) — Démarche diagnostique et thérapeutique séquentielle</h4>","branches":[{"to":"q-gravite","label":"Bilan initial réalisé","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes de gravité ? — AEG, hémoptysie, dyspnée, dysphonie, ADP cervicale, toux du fumeur...","branches":[{"to":"t-specifique","label":"Oui","color":"red"},{"to":"q-cause","label":"Non","color":"green"}]},{"id":"t-specifique","kind":"terminal","label":"Prise en charge spécifique","color":"red","detail":"<h4>Conduite</h4><ul><li>Orientation vers une <span class=\"kw-ttt\">prise en charge spécifique</span> selon l'anomalie</li><li>Compléter le bilan en fonction du signe d'alerte (<span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-imagerie\">endoscopie</span> bronchique...)</li></ul><h4><span class=\"kw-alerte\">Signes de gravité</span></h4><ul><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span></li><li><span class=\"kw-clinique\">Dyspnée</span> d'effort, <span class=\"kw-alerte\">hémoptysie</span></li><li>Modification de la <span class=\"kw-clinique\">toux</span> chez un fumeur, dysphonie, <span class=\"kw-clinique\">dysphagie</span>, fausses routes</li><li><span class=\"kw-clinique\">Adénopathie cervicale suspecte</span>, anomalie cardio-pulmonaire</li></ul>"},{"id":"q-cause","kind":"decision","label":"Argument pour une cause fréquente (STOVAS / asthme / RGO) ? — Après EVA + arrêt tabac et tussigènes (IEC, sartans, gliptines) pendant 4 semaines","branches":[{"to":"q-epreuve","label":"Oui (cause évoquée)","color":"amber"},{"to":"t-bilan2","label":"Non (absence d'argument)","color":"blue"}]},{"id":"q-epreuve","kind":"decision","label":"Traitement d'épreuve ciblé efficace ? — STOVAS, asthme ou RGO","branches":[{"to":"t-confirme","label":"Oui","color":"green"},{"to":"t-echec","label":"Non","color":"amber"}]},{"id":"t-confirme","kind":"terminal","label":"Diagnostic confirmé — poursuite du traitement","color":"green","detail":"<h4>Conduite</h4><ul><li>Poursuivre le <span class=\"kw-ttt\">traitement étiologique</span> efficace</li><li>Maintenir le <span class=\"kw-ttt\">sevrage tabagique</span></li></ul><h4>Traitements d'épreuve (rappel)</h4><ul><li>STOVAS : <span class=\"kw-ttt\">corticothérapie nasale</span> + lavage du nez</li><li>Asthme : <span class=\"kw-ttt\">CSI</span> ± <span class=\"kw-ttt\">BDLA</span></li><li><span class=\"kw-clinique\">RGO</span> : <span class=\"kw-ttt\">IPP</span> <span class=\"kw-chiffre\">≥ 8 semaines</span> + <span class=\"kw-ttt\">règles hygiéno-diététiques</span></li></ul>"},{"id":"t-echec","kind":"terminal","label":"Échec malgré traitement bien conduit","color":"amber","detail":"<h4>Conduite</h4><ul><li>Vérifier l'observance et la durée du <span class=\"kw-ttt\">traitement d'épreuve</span></li><li>Compléter par un bilan étiologique de <span class=\"kw-chiffre\">2e ligne</span></li><li>Évoquer une <span class=\"kw-etio\">toux réfractaire</span> si bilan négatif</li></ul>"},{"id":"t-bilan2","kind":"terminal","label":"Bilan étiologique de 2e ligne orienté","color":"blue","detail":"<h4>Bilan de <span class=\"kw-chiffre\">2e ligne</span> (selon contexte)</h4><ul><li><span class=\"kw-bio\">pH-métrie des 24h</span> + manométrie œsophagienne</li><li><span class=\"kw-imagerie\">TDM thoracique</span> ; <span class=\"kw-imagerie\">TDM des sinus</span></li><li><span class=\"kw-imagerie\">Endoscopie bronchique</span></li><li>Enregistrement du sommeil (polysomnographie)</li><li>Évaluation cardiaque : <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-imagerie\">échographie cardiaque</span></li></ul><h4>Si absence de cause ou persistance</h4><ul><li><span class=\"kw-etio\">Toux réfractaire</span> ou inexpliquée = syndrome de <span class=\"kw-clinique\">toux</span> par excès de sensibilité (TOCRI)</li><li>Traitement : <span class=\"kw-ttt\">anti-épileptiques</span> (<span class=\"kw-ttt\">prégabaline</span> ou <span class=\"kw-ttt\">gabapentine</span>) + <span class=\"kw-ttt\">morphine</span> à faible dose</li></ul>"}]},"cards":[{"i":"1f5e86f3c44e","n":204,"o":"204-1","u":"Définition","t":"Connaître la définition de la toux aiguë et chronique chez l'enfant et l'adulte","q":"Comment définit-on une toux chronique chez l'adulte et l'enfant ?","a":"<p>Une toux est dite chronique lorsqu'elle évolue depuis <strong>plus de 8 semaines</strong>. Elle ne s'améliore pas spontanément et nécessite une prise en charge spécifique, même si elle est isolée. La durée de <strong>8 semaines</strong> est un cap important pour orienter la démarche diagnostique.</p>"},{"i":"208e01a6a63e","n":204,"o":"204-1","u":"Définition","t":"Connaître la définition de la toux aiguë et chronique chez l'enfant et l'adulte","q":"Comment définit-on une toux aiguë chez l'adulte et l'enfant ?","a":"<p>Une toux est dite aiguë lorsqu'elle évolue depuis <strong>moins de 3 semaines</strong>. Elle est souvent secondaire aux infections respiratoires hautes d'origine virale et s'améliore spontanément.</p>"},{"i":"8b8003670f02","n":204,"o":"204-1","u":"Définition","t":"Connaître la définition de la toux aiguë et chronique chez l'enfant et l'adulte","q":"Quelle est la définition physiologique de la toux en médecine ?","a":"<p>La toux est l'<strong>expulsion brusque et sonore de l'air</strong> contenu dans les poumons. C'est un <strong>phénomène réflexe physiologique</strong>, indispensable à l'épuration et à la protection des voies aériennes.</p>"},{"i":"43153b5e4a8a","n":204,"o":"204-3","u":"Identifier une urgence","t":"Rechercher les signes de gravité devant une toux aiguë ou chronique","q":"Quels sont les signes à l'examen clinique qui doivent alerter devant une toux aiguë ou chronique, chez l'adulte ou l'enfant ?","a":"<p>À l'examen clinique, les signes d'alerte sont :</p><ul><li>Des <strong>adénopathies cervicales suspectes</strong>.</li><li>Des <strong>anomalies de l'auscultation ou de l'inspection cardiopulmonaire</strong>.</li></ul>"},{"i":"4722a0eefb59","n":204,"o":"204-3","u":"Identifier une urgence","t":"Rechercher les signes de gravité devant une toux aiguë ou chronique","q":"Quels sont les signes spécifiques de gravité devant une toux chronique chez l'enfant ?","a":"<p>Chez l'enfant, les signes de gravité spécifiques d'une toux chronique incluent :</p><ul><li><strong>Respiratoires</strong> : encombrement bronchique permanent, wheezing ou stridor permanents, dyspnée aux deux temps.</li><li><strong>Digestifs/nutritionnels</strong> : fausses routes alimentaires, cassure de la croissance staturo-pondérale, diarrhée chronique.</li><li><strong>Cardiovasculaires</strong> : malaise avec cyanose, souffle cardiaque.</li><li><strong>État général</strong> : altération de l'état général, limitation des activités, retentissement sur le sommeil.</li><li><strong>Autres</strong> : infections à répétition ou opportunistes, déformation thoracique, hippocratisme digital.</li></ul>"},{"i":"c164a76426fc","n":204,"o":"204-3","u":"Identifier une urgence","t":"Rechercher les signes de gravité devant une toux aiguë ou chronique","q":"Quels sont les signes généraux qui doivent alerter devant une toux aiguë ou chronique, chez l'adulte ou l'enfant ?","a":"<p>Devant une toux aiguë ou chronique, les signes généraux alarmants sont :</p><ul><li>Une <strong>altération de l'état général (AEG)</strong> : asthénie, anorexie, amaigrissement.</li><li>Un <strong>syndrome infectieux</strong> : fièvre persistante, sueurs.</li></ul>"},{"i":"df6362f98ea2","n":204,"o":"204-3","u":"Identifier une urgence","t":"Rechercher les signes de gravité devant une toux aiguë ou chronique","q":"Quels sont les symptômes respiratoires et ORL qui doivent alerter devant une toux aiguë ou chronique, chez l'adulte ou l'enfant ?","a":"<p>Les symptômes respiratoires et ORL qui doivent alerter sont :</p><ul><li>Une <strong>dyspnée d'effort</strong>.</li><li>Une <strong>hémoptysie</strong>.</li><li>Une <strong>modification de la toux</strong> ou son apparition chez un <strong>fumeur</strong>.</li><li>Des signes ORL : <strong>dysphonie</strong>, <strong>dysphagie</strong>, <strong>fausses routes</strong>.</li></ul>"},{"i":"6ae8a3292e33","n":204,"o":"204-4","u":"Diagnostic positif","t":"Connaître la sémiologie d'une toux et les signes associés à la toux","q":"Quelles sont les caractéristiques de la toux à préciser à l'interrogatoire pour orienter le diagnostic étiologique ?","a":"<p>Il faut évaluer à l'interrogatoire :</p><ul><li>Le caractère <strong>productif ou sec</strong> de la toux.</li><li>Son <strong>horaire</strong> (diurne, nocturne, matinale).</li><li>Son <strong>ancienneté</strong> (aiguë, subaiguë, chronique).</li><li>Les <strong>circonstances déclenchantes</strong> (effort, décubitus, repas, air froid, parfums).</li></ul>"},{"i":"9c30de0c73cd","n":204,"o":"204-4","u":"Diagnostic positif","t":"Connaître la sémiologie d'une toux et les signes associés à la toux","q":"Quelles sont les complications physiques mécaniques de la toux à rechercher ?","a":"<p>Les complications physiques de la toux peuvent inclure :</p><ul><li>Des <strong>céphalées</strong>.</li><li>Des <strong>vomissements</strong>.</li><li>Des <strong>fractures de côtes</strong>.</li><li>Une <strong>hernie inguinale</strong>.</li><li>Une <strong>incontinence urinaire</strong>, particulièrement fréquente chez les femmes.</li></ul>"},{"i":"e5592d64031a","n":204,"o":"204-4","u":"Diagnostic positif","t":"Connaître la sémiologie d'une toux et les signes associés à la toux","q":"Quels sont les signes associés à la toux qui doivent orienter vers une étiologie particulière ?","a":"<ul><li>Un <strong>pyrosis</strong> ou des <strong>régurgitations acides</strong> orientent vers un reflux gastro-œsophagien (RGO).</li><li>Un <strong>jetage postérieur</strong>, une <strong>rhinorrhée</strong> ou une <strong>obstruction nasale</strong> orientent vers une rhinosinusite chronique (STOVAS).</li><li>Des <strong>sibilants</strong> ou une <strong>dyspnée d'effort</strong> orientent vers un asthme.</li><li>Une <strong>pyrexie</strong> ou une <strong>expectoration purulente</strong> orientent vers une infection respiratoire.</li></ul>"},{"i":"0890da964752","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Face à une toux aiguë chez l'enfant, quelles sont les étiologies à évoquer spécifiquement si la toux est de type grasse ?","a":"<p>Si la toux aiguë de l'enfant est de type grasse, les étiologies à évoquer sont la <strong>rhinopharyngite</strong> et les <strong>infections ORL</strong>, souvent majorées au décubitus, avec rhinite et parfois fébricule.</p>"},{"i":"160b1a8b1aab","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Quel est le réflexe à ne pas avoir devant une toux aiguë sans signe d'alerte, selon les recommandations ?","a":"<p>Le réflexe à ne pas avoir est de prescrire d'emblée une <strong>radiographie thoracique</strong> (RXT) ou des <strong>antibiotiques</strong> sur une toux aiguë sans signe d'alerte, étant donné que la majorité des toux aiguës sont virales et se résolvent spontanément.</p>"},{"i":"2b127ad28131","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Quelles sont les causes rares mais graves de toux aiguë à ne pas manquer chez l'adulte ?","a":"<ul><li><strong>Cardiaques</strong> : insuffisance cardiaque gauche</li><li><strong>Vasculaires</strong> : embolie pulmonaire</li><li><strong>Pleuro-pulmonaires</strong> : pneumothorax, pleurésies</li></ul>"},{"i":"77ca01513641","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Quelles sont les étiologies les plus fréquentes de la toux aiguë chez l'adulte et l'enfant ?","a":"<p>Les étiologies les plus fréquentes de la toux aiguë sont les <strong>infections respiratoires hautes virales</strong>, notamment la rhinopharyngite aiguë et la rhino-sinusite aiguë.</p>"},{"i":"952c294f5de6","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Quelle est la définition temporelle d'une toux aiguë, selon le contexte de l'EDN ?","a":"<p>Selon le contexte de l'EDN, une toux aiguë est une toux dont la durée est <strong>inférieure à 3 semaines</strong>.</p>"},{"i":"c3928bdeb46a","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Face à une toux aiguë chez l'enfant, quelles sont les étiologies à évoquer spécifiquement si la toux est de type sèche ?","a":"<ul><li><strong>Asthme</strong></li><li><strong>Bronchiolite</strong> (avec wheezing, dyspnée, sibilants)</li><li><strong>Pneumonie</strong> (avec fièvre, polypnée, crépitants en foyer)</li><li><strong>Coqueluche</strong> (toux quinteuse, vaccination incomplète)</li><li><strong>Corps étranger inhalé</strong> (toux brutale, syndrome d'inhalation, dyspnée)</li></ul>"},{"i":"e1f2267958e8","n":204,"o":"204-5","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux aiguë de l'enfant et l'adulte","q":"Quels sont les examens complémentaires à réaliser en routine devant une toux aiguë, en l'absence de signes d'alerte ?","a":"<p>En l'absence de signes d'alerte, <strong>aucun examen complémentaire</strong> n'est nécessaire en routine devant une toux aiguë. Une radiographie thoracique n'est envisagée que si l'examen clinique est anormal.</p>"},{"i":"4344b46f8b84","n":204,"o":"204-6","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","q":"Quelles sont les trois étiologies les plus fréquentes de la toux chronique de l'adulte, à évoquer en première intention ?","a":"<ul><li>Les pathologies des <strong>voies aériennes supérieures</strong> : notamment la rhinosinusite chronique (STOVAS).</li><li>Les pathologies des <strong>voies aériennes inférieures</strong> : principalement l'asthme.</li><li>Les pathologies <strong>digestives</strong> : le reflux gastro-œsophagien (RGO).</li></ul>"},{"i":"574dbfdf9840","n":204,"o":"204-6","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","q":"Quelles sont les spécificités cliniques d'une toux chronique faisant évoquer une mucoviscidose ou une autre DDB chez l'enfant ?","a":"<p>Il s'agit d'une toux <strong>grasse avec expectoration</strong>, souvent de <strong>début précoce</strong>, associée à une <strong>cassure pondérale</strong>, un <strong>hippocratisme digital</strong> et des <strong>crépitants</strong> à l'auscultation.</p>"},{"i":"ccf5ecd0313b","n":204,"o":"204-6","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","q":"Quelles sont les caractéristiques permettant de suspecter une toux psychogène chez l'enfant ?","a":"<p>Une toux psychogène peut être suspectée si elle est <strong>aboyante</strong>, <strong>diurne</strong>, qu'elle <strong>s'arrête sur commande</strong>, et qu'elle survient sur un <strong>terrain anxieux</strong> ou avec des <strong>tics</strong>, sans déclencheur organique clair.</p>"},{"i":"d275735efcc9","n":204,"o":"204-6","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","q":"Qu'est-ce que le syndrome de toux par excès de sensibilité (TOCRI) et quelles en sont les manifestations cliniques ?","a":"<p>Le <strong>Syndrome de Toux par Excès de Sensibilité (TOCRI)</strong> est dû à une <strong>sensibilisation des voies neurologiques de la toux</strong>. Cliniquement, il se manifeste par des <strong>irritations/paresthésies</strong> des voies aériennes supérieures, une <strong>hypertussie</strong> (déclenchement par stimuli peu tussigènes), une <strong>allotussie</strong> (déclenchement par stimuli non tussigènes comme la parole ou le rire), et une <strong>toux paroxystique difficile à contrôler</strong>.</p>"},{"i":"ef08582cc18e","n":204,"o":"204-6","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","q":"Quels sont les éléments clés à rechercher à l'interrogatoire en cas de toux chronique de l'adulte, avant d'engager un bilan paraclinique poussé ?","a":"<p>Il faut systématiquement rechercher une prise <strong>d'IEC (inhibiteur de l'enzyme de conversion)</strong>. C'est une cause fréquente de toux sèche, qui peut apparaître jusqu'à <strong>6 mois</strong> après l'instauration du traitement.</p>"},{"i":"f08bcdaad3dc","n":204,"o":"204-6","u":"Diagnostic positif","t":"Connaître les principales hypothèses diagnostiques d'une toux chronique de l'enfant et l'adulte","q":"Comment définit-on une toux chronique, chez l'adulte comme chez l'enfant ?","a":"<p>Une toux est définie comme <strong>chronique</strong> si elle persiste au-delà de <strong>8 semaines</strong>.</p>"},{"i":"0030bd0bdc80","n":204,"o":"204-7","u":"Contenu multimédia","t":"Exemples caractéristiques de radiographie thoracique","q":"Quelle est l'image radiologique caractéristique du syndrome bronchique (dilatation des bronches) sur un cliché de radiographie thoracique de face ?","a":"<p>Le syndrome bronchique (dilatation des bronches ou DDB) se caractérise sur une radiographie thoracique par des images en <strong>cibles</strong> (bronches dilatées à parois épaisses), des images en <strong>rail</strong>, et parfois un <strong>nodule bien limité</strong> correspondant à une impaction mucoïde.</p>"},{"i":"69bad3b11d59","n":204,"o":"204-7","u":"Contenu multimédia","t":"Exemples caractéristiques de radiographie thoracique","q":"Dans le cadre de la toux, quelles sont les principales étiologies ayant des radiographies thoraciques caractéristiques abordées dans d'autres items ?","a":"<ul><li>La <strong>pneumopathie interstitielle</strong> est abordée dans l'item 210.</li><li>Les <strong>opacités et masses intra-thoraciques</strong> sont abordées dans l'item 207.</li></ul>"},{"i":"75c0c14f48f9","n":204,"o":"204-7","u":"Contenu multimédia","t":"Exemples caractéristiques de radiographie thoracique","q":"Quel type de cliché radiologique est particulièrement utile pour le diagnostic d'un corps étranger inhalé chez l'enfant ?","a":"<p>Pour le diagnostic d'un corps étranger inhalé chez l'enfant, des clichés en <strong>inspiration et expiration forcée</strong> sont particulièrement utiles pour mettre en évidence un trappage aérien.</p>"},{"i":"0388766521f4","n":204,"o":"204-9","u":"Prise en charge","t":"Connaître le traitement symptomatique de la toux","q":"Quelle est l'attitude générale face à la prescription d'antitussifs pour la toux chez l'enfant et l'adulte ?","a":"<p>Le principe est de <strong>ne pas</strong> prescrire les antitussifs en routine en raison d'un <strong>rapport bénéfice/risque faible</strong>. Leur efficacité n'est pas clairement démontrée, et ils présentent des effets secondaires parfois importants. Le traitement repose principalement sur la <strong>prise en charge étiologique</strong> de la toux.</p>"},{"i":"43819aac90d9","n":204,"o":"204-9","u":"Prise en charge","t":"Connaître le traitement symptomatique de la toux","q":"Quelles sont les principales classes d'antitussifs agissant par action centrale, et quels sont leurs exemples ?","a":"<ul><li><strong>Opiacés narcotiques</strong> : codéine, pholcodine</li><li><strong>Opiacés non narcotiques</strong> : dextrométhorphane, noscapine</li><li><strong>Antihistaminiques H1 sédatifs</strong> : alimémazine, prométhazine</li><li><strong>Non opiacés, non antihistaminiques</strong> : oxéladine, pentoxyvérine, clobutinol</li></ul>"},{"i":"e15e255f0b09","n":204,"o":"204-9","u":"Prise en charge","t":"Connaître le traitement symptomatique de la toux","q":"Quelles sont les contre-indications majeures ou précautions à connaître concernant la codéine et les opiacés en général pour la toux ?","a":"<ul><li>La <strong>codéine</strong> est formellement <strong>contre-indiquée chez l'enfant de moins de 12 ans</strong> en raison du risque de dépression respiratoire. Elle doit également être évitée chez la femme allaitante.</li><li>Les <strong>opiacés en général</strong> nécessitent une prudence chez l'<strong>insuffisant respiratoire chronique</strong>, le <strong>sujet âgé</strong> et l'<strong>insuffisant hépatique</strong>.</li><li>Les antitussifs sont <strong>déconseillés en cas de toux productive</strong> car ils bloquent le réflexe d'épuration bronchique.</li></ul>"},{"i":"e4439189f695","n":204,"o":"204-9","u":"Prise en charge","t":"Connaître le traitement symptomatique de la toux","q":"Quelles sont les mesures non médicamenteuses systématiques pour le traitement symptomatique de la toux ?","a":"<ul><li><strong>Arrêt du tabac</strong> avec aide au sevrage si le patient est un fumeur actif.</li><li><strong>Hydratation</strong> adéquate.</li><li><strong>Évitement des facteurs déclenchants</strong> identifiés de la toux.</li></ul>"}]};